{
"summary": "The Lean file states Ehrhart's sharp volume bound: a compact convex set S in ℝⁿ with nonempty interior, barycenter 0 and interior lattice points exactly {0} has Lebesgue volume at most (n+1)ⁿ/n!. It also states sharpness: the simplex (n+1)Δₙ − (1,…,1) has barycenter 0 and volume (n+1)ⁿ/n!, and a `CenteredBody` attaining the bound exists for n>0. The statements look faithful; the main caveats are cosmetic (the name `normalizedVolume` is just Lebesgue volume, and `hn : 0 ≤ n` is vacuous).",
"glossary": [
{"decl":"Ehrhart.Space","line":10,"plain":"ℝⁿ as Fin n → ℝ with the product (sup-norm) topology and product Lebesgue measure","standard_concept":"Euclidean space ℝⁿ","matches_standard":"yes","note":"Same topology, interior and Lebesgue measure as the Euclidean structure."},
{"decl":"Ehrhart.integerPoint","line":12,"plain":"Casts z ∈ ℤⁿ into ℝⁿ coordinatewise","standard_concept":"ℤⁿ ⊂ ℝⁿ","matches_standard":"yes","note":""},
{"decl":"Ehrhart.standardSimplex","line":15,"plain":"{x : xᵢ ≥ 0, Σxᵢ ≤ 1} = conv{0,e₁,…,eₙ}","standard_concept":"Δₙ","matches_standard":"yes","note":""},
{"decl":"Ehrhart.simplexDilation","line":18,"plain":"x ↦ (n+1)x − (1,…,1)","standard_concept":"dilation by n+1 followed by translation by −(1,…,1)","matches_standard":"yes","note":""},
{"decl":"Ehrhart.centeredSimplex","line":21,"plain":"(n+1)Δₙ − (1,…,1)","standard_concept":"the paper's extremal simplex","matches_standard":"yes","note":""},
{"decl":"Ehrhart.normalizedVolume","line":24,"plain":"Lebesgue volume of K as a real number (toReal)","standard_concept":"vol(K)","matches_standard":"yes","note":"The name suggests normalization by n!, but it is plain volume. toReal would give junk 0 for infinite volume, but all uses involve compact sets."},
{"decl":"Ehrhart.barycenter","line":27,"plain":"(vol K)⁻¹ · ∫_K x dx","standard_concept":"center of mass","matches_standard":"yes","note":"Junk values (division by zero, non-integrability) only arise for null or unbounded sets, which are excluded by the hypotheses."},
{"decl":"Ehrhart.interiorLatticePoints","line":30,"plain":"{z ∈ ℤⁿ : z ∈ int K}","standard_concept":"int(K) ∩ ℤⁿ","matches_standard":"yes","note":""},
{"decl":"Ehrhart.CenteredBody","line":33,"plain":"Compact convex set with nonempty interior, barycenter 0, and interior lattice points exactly {0}","standard_concept":"hypotheses of Theorem 1.1","matches_standard":"yes","note":"Full-dimensional is encoded as nonempty interior."},
{"decl":"Ehrhart.sharpConstant","line":41,"plain":"(n+1)ⁿ/n!","standard_concept":"bound in (1)","matches_standard":"yes","note":""}
],
"lean_claims": [
{"theorem":"Ehrhart.SimplexVolume.barycenter_centeredSimplex","line":48,"plain":"For every n, the barycenter of (n+1)Δₙ − (1,…,1) is 0."},
{"theorem":"Ehrhart.SimplexVolume.normalizedVolume_centeredSimplex","line":52,"plain":"For n>0, vol((n+1)Δₙ − (1,…,1)) = (n+1)ⁿ/n!."},
{"theorem":"Ehrhart.SimplexVolume.exists_centeredBody_sharp","line":56,"plain":"For n>0 there is a compact convex set with nonempty interior, barycenter 0 and interior lattice points {0} whose volume is (n+1)ⁿ/n!."},
{"theorem":"Ehrhart.Volume.ehrhart_volume_inequality_for_sets","line":65,"plain":"For every n and every compact convex S ⊂ ℝⁿ with nonempty interior, barycenter 0 and int(S) ∩ ℤⁿ = {0}, vol(S) ≤ (n+1)ⁿ/n!."}
],
"paper_claims": [
{"ref":"Theorem 1.1","plain":"A full-dimensional compact convex body K ⊂ ℝⁿ with barycenter 0 and int(K) ∩ ℤⁿ = {0} has vol(K) ≤ (n+1)ⁿ/n!."},
{"ref":"Sharpness remark (after Thm 1.1)","plain":"The simplex (n+1)Δₙ − (1,…,1) has barycenter 0, no other interior lattice point, and volume (n+1)ⁿ/n!."}
],
"coverage": [
{"paper_ref":"Theorem 1.1","lean_theorem":"Ehrhart.Volume.ehrhart_volume_inequality_for_sets","relation":"equivalent","why":"Same hypotheses and conclusion; also covers n=0, where it holds (1 ≤ 1)."},
{"paper_ref":"Sharpness remark: barycenter 0","lean_theorem":"Ehrhart.SimplexVolume.barycenter_centeredSimplex","relation":"equivalent","why":"Direct formalization."},
{"paper_ref":"Sharpness remark: volume","lean_theorem":"Ehrhart.SimplexVolume.normalizedVolume_centeredSimplex","relation":"equivalent","why":"Direct formalization for n>0."},
{"paper_ref":"Sharpness remark: no other interior lattice point and bound attained","lean_theorem":"Ehrhart.SimplexVolume.exists_centeredBody_sharp","relation":"equivalent","why":"Existential packaging of the simplex as a CenteredBody; it does not name the simplex explicitly, but that is a faithful rendering of sharpness."}
],
